const counts={lessons:lessons.length,part2:lessons.filter(l=>l.part===2).length,questions:lessons.reduce((n,l)=>n+l.questions.length,0),prep:Object.values(prep).reduce((n,g)=>n+g.questions.length,0)};
const source=id=>sources.find(s=>s.id===id)?.url;

const hubRows=[["POL1101","การเมืองการปกครองไทย","8","772"],["POL2106","ปรัชญาการเมืองเบื้องต้น","18","1767"],["POL2107","การเมืองเปรียบเทียบเบื้องต้น","17","1695"],["POL2200","ความสัมพันธ์ระหว่างประเทศเบื้องต้น","19","1923"],["POL2301","องค์การและการบริหารในภาครัฐ","6","544"],["POL2303","การบริหารทรัพยากรมนุษย์ในภาครัฐ","15","1498"],["RAM1101","ทักษะการใช้ภาษาไทย","6","720"],["RAM1103","ภาษาไทยเพื่อการสื่อสารในการทำงาน","8","963"],["RAM1111","ภาษาอังกฤษในชีวิตประจำวัน","9","1080"],["RAM1112","ภาษาและวัฒนธรรมอังกฤษ","6","720"],["RAM1131","ทักษะการเข้าใจดิจิทัล","7","814"],["POL2300","การบริหารรัฐกิจเบื้องต้น","23","2300"],["RAM1301","คุณธรรมคู่ความรู้","6","620"],["POL3300","การบริหารการคลัง","15","1500"],["POL2100","การปกครองเปรียบเทียบ","13","1297"],["POL2108","หลักปฏิบัติทางการปกครองและธรรมาภิบาลในภาครัฐ","19","1860"],["POL3301","นโยบายสาธารณะ","18","1788"],["POL4100","หลักและวิธีการวิจัยทางรัฐศาสตร์","24","2400"],["RAM1201","ความคิดสร้างสรรค์เพื่อการพัฒนานวัตกรรม","7","804"],["RAM1311","ศิลปะและวัฒนธรรมในท้องถิ่นไทย","8","958"],["ACC1101","การบัญชีขั้นต้น 1","3","221"],["ACC1103","การบัญชีขั้นต้น","6","439"],["RAM1204","คณิตศาสตร์และสถิติเพื่อการดำเนินชีวิตในโลกสมัยใหม่","5","300"],["RAM1132","ทักษะทางสารสนเทศ","6","717"],["LAW1101","หลักกฎหมายมหาชน","1","120"],["POL2109","การเมืองและการปกครองท้องถิ่นในประเทศไทย","0","0"],["ECO1121","เศรษฐศาสตร์จุลภาค","4","398"],["RAM1302","การเมืองและกฎหมายในชีวิตประจำวัน","5","600"],["RAM1213","ภูมิปัญญาท้องถิ่นกับการพัฒนานวัตกรรมเพื่อสังคมและเศรษฐกิจ","5","556"],["RAM1142","การพัฒนาคุณภาพชีวิตและสังคม","5","599"],["RAM1141","ศาสตร์แห่งบุคลิกภาพ","9","1074"]];
const hubNotes={"POL1101":["ศาลและองค์กรอิสระ • การปกครองก่อน 2475 • คณะรัฐมนตรี","ภาค 2/2568 · 100 ข้อ","เลือกองค์กรอิสระหนึ่งแห่ง แล้วเทียบว่าใครแต่งตั้ง มีหน้าที่อะไร และตรวจสอบใครได้"],"POL2106":["ผู้ปกครองที่ชอบธรรม • เหตุผลที่คนรวมเป็นรัฐ • การกระจายทรัพย์สิน","ภาค 2/2568 · 100 ข้อ","ถ้ารัฐเก็บภาษีเพื่อลดความเหลื่อมล้ำ นักคิดสองสำนักจะให้เหตุผลต่างกันอย่างไร?"],"POL2107":["แนวทางและทฤษฎีเปรียบเทียบ • รูปแบบรัฐ • วิธีเลือกกรณีศึกษา","ภาค 2/2568 · 100 ข้อ","เลือกสองประเทศที่ใช้ระบบรัฐสภา แล้วระบุตัวแปรที่จะใช้อธิบายว่าทำไมรัฐบาลจึงมีเสถียรภาพต่างกัน"],"POL2200":["องค์การระหว่างประเทศ • ลำดับเหตุการณ์สำคัญ • ระบบรัฐ","ซ่อม 2/68 และฤดูร้อน 68 ชุด 1 · 98 ข้อ","เปรียบเทียบอำนาจตัดสินใจของอาเซียนกับสหประชาชาติผ่านกรณีข้อพิพาทเดียวกัน"],"POL2301":["โครงสร้างองค์การ • การตัดสินใจและควบคุม • ทฤษฎีระบบ","ฤดูร้อน 2568 · 99 ข้อ","วาดผังหน่วยงานที่รู้จัก แล้วชี้ว่าถ้ากระจายอำนาจ ขั้นตอนตัดสินใจใดจะสั้นลง"],"POL2303":["กระบวนการบริหารคน • ระบบบุคลากรภาครัฐไทย • ค่าตอบแทนและการคัดเลือก","ภาค 1/2568 · 99 ข้อ","แยกการประเมินค่างานออกจากการประเมินผลงาน โดยยกตัวอย่างพนักงานคนเดียวกัน"]};
const hubLink='<a class="button secondary small" href="https://ram-test-hub.pages.dev/" target="_blank" rel="noopener noreferrer">เปิดคลังข้อสอบราม ↗</a>';
function hubCard(row){const [code,title,sets,count]=row,n=hubNotes[code];return `<article><h3>${code} · ${title}</h3><p>${code==='POL2109'?'ข้อเขียน 8 ชุด':sets+' ชุด · '+count+' ข้อ'+(code==='LAW1101'?' และข้อเขียน 83 ชุด':'')} ตามหน้าคลัง</p>${n?`<p><b>เริ่มอ่าน:</b> ${n[0]}</p><p><b>ลองตอบก่อนเปิดเฉลย:</b> ${n[2]}</p><p><b>ชุดฝึกฟรี:</b> เลือก ${code} → ฝึกข้อสอบ → ${n[1]}</p>`:''}</article>`;}
function hubSection(){return `<section class="panel"><h2>คลังข้อสอบราม · ภาค 2/2569</h2><p>เลือกวิชาเพื่อดูหัวข้อและชุดฝึกที่เริ่มได้ฟรี จำนวนบนการ์ดต้นทางรวมชุดเสริมบางชุดด้วย ตรวจเมื่อ 5 พ.ย. 2569</p>${hubLink}${hubRows.filter(r=>hubNotes[r[0]]).map(r=>`<details><summary>${r[0]} · ${r[1]}</summary>${hubCard(r)}</details>`).join('')}<p>POL2104 ยังไม่พบในคลังนี้</p><details><summary>วิชาสำรอง · 25 วิชา</summary>${hubRows.filter(r=>!hubNotes[r[0]]).map(hubCard).join('')}</details></section>`;}

export function courseResources(code){
 const row=hubRows.find(r=>r[0]===code);
 return `${row?`<section class="panel">${hubCard(row)}${hubLink}</section>`:""}<section class="course-resources"><div><h2>เรียนวิชานี้ให้ครบวงจร</h2><p>ใช้รหัส <b>${code}</b> ค้นคำบรรยายและตำรา ตรวจภาคเรียนและฉบับกับผู้สอน</p></div><div class="resource-actions"><a class="button primary" href="${e(source('video'))}" target="_blank" rel="noopener noreferrer">▶ ดูย้อนหลัง</a><a class="button secondary" href="${e(source('live'))}" target="_blank" rel="noopener noreferrer">● เรียนสด</a><a class="button secondary" href="${e(source('bookstore'))}" target="_blank" rel="noopener noreferrer">หาตำรา / ซื้อหนังสือ ↗</a><a class="button secondary" href="#prep/${code}">ฝึกข้อสอบ →</a></div><p class="quiet-note">ลิงก์เปิดเว็บมหาวิทยาลัยในแท็บใหม่ ใช้บัญชีและสิทธิ์ของคุณในระบบนั้น วิดีโอและหนังสือไม่ได้คัดลอกมาเก็บในแอป</p></section>`;
}
export function resourcesPage(state){
 return `<div class="page-heading"><div><div class="eyebrow">MY LEARNING DESK</div><h1>แหล่งเรียนออนไลน์</h1><p>เริ่มจากพื้นฐาน → เรียนกับมหาวิทยาลัย → จดสรุป → ฝึกตอบและทบทวน</p></div><a class="button secondary" href="#calendar">ดูปฏิทินเรียน–สอบ →</a></div>
 ${hubSection()}<div class="learning-portals"><a class="learning-portal online" href="${e(source('video'))}" target="_blank" rel="noopener noreferrer"><span class="portal-icon">▶</span><div><small>คำบรรยายของมหาวิทยาลัย</small><h2>RU on Demand</h2><p>ดูวิดีโอย้อนหลัง ค้นรหัสวิชา เลือกส่วนกลางและภาคที่ต้องการเมื่อมีเผยแพร่</p><b>ดูย้อนหลัง ↗</b></div></a><a class="learning-portal live" href="${e(source('live'))}" target="_blank" rel="noopener noreferrer"><span class="portal-icon">●</span><div><small>ถ่ายทอดตามตาราง ม.ร.30</small><h2>Cyber Classroom</h2><p>เรียนสด เลือกส่วนกลางและห้องของวิชา ให้ตรงกับตารางที่มหาวิทยาลัยประกาศ</p><b>เปิดเรียนสด ↗</b></div></a><a class="learning-portal books" href="${e(source('bookstore'))}" target="_blank" rel="noopener noreferrer"><span class="portal-icon">▤</span><div><small>ตำราและเอกสารการเรียน</small><h2>ร้านหนังสือรามคำแหง</h2><p>ค้นตำราด้วยรหัสวิชา ตรวจชื่อผู้แต่งและฉบับที่อาจารย์ใช้ก่อนซื้อ</p><b>เปิดร้านหนังสือมหาวิทยาลัย ↗</b></div></a></div>
 <section class="panel"><h2>เวลาเรียนชนกัน ทำอย่างไร?</h2><p>สำหรับวิชาที่บรรยายเวลาเดียวกัน เลือกสดหนึ่งวิชา แล้วย้อนหลังอีกวิชาได้เมื่อมีคลิป หรือดูย้อนหลังทั้งคู่ถ้าผู้สอนไม่กำหนดกิจกรรมสด ตรวจประกาศของแต่ละวิชาก่อน</p><p>ตรวจห้องเรียนของวิชากับ <a href="${e(source('cyber-rooms'))}" target="_blank" rel="noopener noreferrer">รายชื่อห้องที่มีถ่ายทอดและบันทึก ↗</a> และตรวจว่าคลิปภาคที่เรียนเผยแพร่แล้ว</p><p>RU on Demand ใช้บัญชีมหาวิทยาลัย RU e-Service ส่วนบัญชีของแอปนี้ใช้เก็บโน้ตและความคืบหน้า ทั้งสองระบบแยกกัน</p><p><a href="${e(source('video-announcement'))}" target="_blank" rel="noopener noreferrer">อ่านประกาศระบบย้อนหลังจากมหาวิทยาลัย ↗</a> · <a href="#calendar">ดูวิชาที่เวลาเรียนชนกัน →</a> · <a href="#about">ลิงก์ต้นฉบับและสำเนาตาราง →</a></p></section>
 <div class="desk-flow"><div><b>01 · ปูพื้นฐาน</b><span>อ่านสรุปและทำความรู้จักคำสำคัญ</span></div><div><b>02 · เรียนเนื้อหาจริง</b><span>ฟังคำบรรยายและอ่านตำรา</span></div><div><b>03 · จดด้วยภาษาตัวเอง</b><span>บันทึกประเด็นเพิ่มในแต่ละบท</span></div><div><b>04 · ทบทวนและฝึกสอบ</b><span>แฟลชการ์ด ข้อที่ผิด และข้อสอบฝึก</span></div></div>
 <div class="section-heading"><div><h2>รายวิชาของฉัน</h2><p>ทางลัดไปบทเรียนและหัวข้อพื้นฐานที่มีในแอป</p></div></div><div class="desk-courses">${courses.filter(c=>c.enrolled).map(c=>{const ls=lessons.filter(l=>l.course===c.id),p=courseProgress(state,c.id);return `<article class="panel desk-course"><div class="desk-course-head"><span class="cc-code">${c.id}</span><b>${p.done}/${p.total} บทพื้นฐาน</b></div><h2>${e(c.title)}</h2><ol>${ls.map(l=>`<li><a href="#lesson/${l.id}">${e(l.title)}</a>${state.completed.includes(l.id)?' <span class="completed-label">อ่านแล้ว ✓</span>':''}</li>`).join('')}</ol><div class="button-row"><a class="button primary small" href="#course/${c.id}">เข้าห้องเรียน →</a><a class="button secondary small" href="#prep/${c.id}">ฝึกข้อสอบ</a></div></article>`;}).join('')}</div>
 <section class="panel coverage-note"><h2>ขอบเขตเนื้อหาของห้องเรียนนี้</h2><p>รวมบทเรียน ${counts.lessons} บท${counts.part2?` (ภาค 1 พื้นฐาน ${counts.lessons-counts.part2} บท · ภาค 2 เจาะตำรา ${counts.part2} บท พร้อมแหล่งอ้างอิงท้ายบท)`:''} คำถามท้ายบท ${counts.questions} ข้อ และข้อสอบฝึกแต่งใหม่ ${counts.prep} ข้อ พร้อมแผนอ่านและสมุดบันทึก เนื้อหาในแอปยังไม่ใช่ตำราเต็มหรือขอบเขตสอบที่มหาวิทยาลัยรับรอง ให้ใช้คำบรรยายและตำราของผู้สอนเป็นหลัก</p><a href="#about" class="text-link">ดูแหล่งอ้างอิงและรายละเอียด →</a></section>`;
}
